// Generated from the app's data model (lib/app-runtime/data-model.ts). Do not edit: it is
// rewritten whenever the data model changes.

export type Note = {
  id: string
  title: string
  body: string
  createdAt: string
  updatedAt?: string
}

/** Maps a collection name to its record type, for useCollection/useRecord. */
export type Collections = {
  "notes": Note
}

